#!/usr/bin/env node
// Regenerates lib/insights/articles.generated.ts from content/insights/*.json.
// Usage: node scripts/insights/build-manifest.mjs [--check]
//   --check  exit 1 if the generated file is out of date (used by validate.mjs / CI).
import {readdirSync, readFileSync, writeFileSync, existsSync} from 'node:fs';
import {join, dirname} from 'node:path';
import {fileURLToPath} from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', '..');
const contentDir = join(root, 'content', 'insights');
const outFile = join(root, 'lib', 'insights', 'articles.generated.ts');

export function renderManifest() {
  const slugs = readdirSync(contentDir)
    .filter((name) => name.endsWith('.json') && !name.startsWith('_'))
    .map((name) => name.replace(/\.json$/, ''))
    .sort();

  const imports = slugs.map((slug, i) => `import article${i} from '@/content/insights/${slug}.json';`).join('\n');
  const list = slugs.map((_, i) => `  article${i}`).join(',\n');

  return `// AUTO-GENERATED by scripts/insights/build-manifest.mjs — do not edit by hand.
// Add or remove files in content/insights/ and re-run the script.
${imports}

export const rawInsightArticleFiles: unknown[] = [
${list}
];
`;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const next = renderManifest();
  const current = existsSync(outFile) ? readFileSync(outFile, 'utf8') : '';

  if (process.argv.includes('--check')) {
    if (current !== next) {
      console.error('lib/insights/articles.generated.ts is out of date. Run: node scripts/insights/build-manifest.mjs');
      process.exit(1);
    }
    console.log('Insight manifest is up to date.');
  } else {
    writeFileSync(outFile, next);
    console.log(`Wrote ${outFile}`);
  }
}
